int sscanf(const char *str, const char *format, ...) {
    /* Minimal sscanf: %d, %x, %u, %s, %c */
    va_list ap; va_start(ap, format);
    int count = 0;
    const char *s = str;
    while (*format) {
        if (isspace(*format)) { while (isspace(*s)) s++; format++; continue; }
        if (*format != '%') { if (*s != *format) break; s++; format++; continue; }
        format++;
        int l = 0;
        if (*format == 'l') { l = 1; format++; }
        int width = 0;
        while (*format >= '0' && *format <= '9') { width = width*10 + (*format - '0'); format++; }
        switch (*format) {
            case 'd': case 'i': {
                while (isspace(*s)) s++;
                int neg = 0;
                if (*s == '-') { neg = 1; s++; }
                long val = 0;
                int n = 0;
                while (*s >= '0' && *s <= '9' && (!width || n < width)) { val = val*10 + (*s - '0'); s++; n++; }
                if (neg) val = -val;
                if (l) *va_arg(ap, long *) = val;
                else *va_arg(ap, int *) = (int)val;
                count++;
                break;
            }
            case 'u': {
                while (isspace(*s)) s++;
                unsigned long val = 0;
                int n = 0;
                while (*s >= '0' && *s <= '9' && (!width || n < width)) { val = val*10 + (*s - '0'); s++; n++; }
                if (l) *va_arg(ap, unsigned long *) = val;
                else *va_arg(ap, unsigned int *) = (unsigned int)val;
                count++;
                break;
            }
            case 'x': {
                while (isspace(*s)) s++;
                if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
                unsigned long val = 0;
                int n = 0;
                while (isxdigit(*s) && (!width || n < width)) {
                    int d;
                    if (*s >= '0' && *s <= '9') d = *s - '0';
                    else d = tolower(*s) - 'a' + 10;
                    val = val*16 + d; s++; n++;
                }
                if (l) *va_arg(ap, unsigned long *) = val;
                else *va_arg(ap, unsigned int *) = (unsigned int)val;
                count++;
                break;
            }
            case 's': {
                while (isspace(*s)) s++;
                char *d = va_arg(ap, char *);
                int n = 0;
                while (*s && !isspace(*s) && (!width || n < width)) { *d++ = *s++; n++; }
                *d = 0;
                count++;
                break;
            }
            case 'c': {
                char *d = va_arg(ap, char *);
                *d = *s++;
                count++;
                break;
            }
            default: break;
        }
        if (*format) format++;
    }
    va_end(ap);
    return count;
}

